mapper.select:
SELECT FROM coupon
status = #{status}
ORDER BY create_time DESC

mapper.insert:
INSERT INTO coupon (
    name, type, value, condition_amount, start_time, end_time,
    total_count, used_count, status
) VALUES (
    #{name}, #{type}, #{value}, #{conditionAmount}, #{startTime}, #{endTime},
    #{totalCount}, #{usedCount}, #{status}
)

mapper.update:
UPDATE coupon
name = #{name}, type = #{type}, value = #{value}, condition_amount = #{conditionAmount}, start_time = #{startTime}, end_time = #{endTime}, total_count = #{totalCount}, used_count = #{usedCount}, status = #{status},
WHERE id = #{id}

UPDATE coupon
SET used_count = GREATEST(used_count - 1, 0)
WHERE id = #{id}
